values (
  'en-latin-american-independence-trivia',
  'Latin American Independence Trivia: The Wars That Freed a Continent',
  'Eight questions on the heroes, battles and dates of Latin American independence, from the Grito de Dolores to Ayacucho.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"In which year did Miguel Hidalgo launch Mexico''s independence movement with the Grito de Dolores?","options":[{"id":"a","text":"1804","is_correct":false},{"id":"b","text":"1810","is_correct":true},{"id":"c","text":"1821","is_correct":false},{"id":"d","text":"1825","is_correct":false}],"explanation":"On 16 September 1810, Hidalgo called the town of Dolores to arms, starting Mexico''s war of independence."},{"id":"q2","question":"Which leader, born in Caracas, is known as El Libertador for freeing much of South America?","options":[{"id":"a","text":"José de San Martín","is_correct":false},{"id":"b","text":"Bernardo O''Higgins","is_correct":false},{"id":"c","text":"Simón Bolívar","is_correct":true},{"id":"d","text":"Agustín de Iturbide","is_correct":false}],"explanation":"Bolívar led the campaigns that freed Venezuela, Colombia, Ecuador, Peru and Bolivia."},{"id":"q3","question":"Which country declared its independence on 9 July 1816 at the Congress of Tucumán?","options":[{"id":"a","text":"Chile","is_correct":false},{"id":"b","text":"Argentina","is_correct":true},{"id":"c","text":"Peru","is_correct":false},{"id":"d","text":"Uruguay","is_correct":false}],"explanation":"The United Provinces of the Río de la Plata declared independence in San Miguel de Tucumán."},{"id":"q4","question":"Who commanded the patriot army at the Battle of Ayacucho in 1824, which sealed Peruvian independence?","options":[{"id":"a","text":"Simón Bolívar","is_correct":false},{"id":"b","text":"José de San Martín","is_correct":false},{"id":"c","text":"Francisco de Paula Santander","is_correct":false},{"id":"d","text":"Antonio José de Sucre","is_correct":true}],"explanation":"Sucre defeated the royalist army on 9 December 1824, the last great land battle of the independence wars."},{"id":"q5","question":"Which mountain range did José de San Martín cross in 1817 to liberate Chile?","options":[{"id":"a","text":"The Andes","is_correct":true},{"id":"b","text":"The Rocky Mountains","is_correct":false},{"id":"c","text":"The Sierra Madre","is_correct":false},{"id":"d","text":"The Brazilian Highlands","is_correct":false}],"explanation":"San Martín led the Army of the Andes over the cordillera from Mendoza, then won at Chacabuco."},{"id":"q6","question":"Brazil declared its independence from Portugal in 1822 under which leader?","options":[{"id":"a","text":"Tiradentes","is_correct":false},{"id":"b","text":"Dom João VI","is_correct":false},{"id":"c","text":"Dom Pedro I","is_correct":true},{"id":"d","text":"Deodoro da Fonseca","is_correct":false}],"explanation":"Pedro I proclaimed independence with the Grito do Ipiranga on 7 September 1822."},{"id":"q7","question":"Which nation became the first independent state in Latin America and the Caribbean in 1804?","options":[{"id":"a","text":"Mexico","is_correct":false},{"id":"b","text":"Paraguay","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"Haiti","is_correct":true}],"explanation":"Haiti declared independence on 1 January 1804 after the revolution led by Dessalines and Louverture."},{"id":"q8","question":"Which 1819 battle secured the independence of New Granada, present-day Colombia?","options":[{"id":"a","text":"Boyacá","is_correct":true},{"id":"b","text":"Carabobo","is_correct":false},{"id":"c","text":"Chacabuco","is_correct":false},{"id":"d","text":"Pichincha","is_correct":false}],"explanation":"Bolívar''s victory at the Boyacá bridge on 7 August 1819 opened the road to Bogotá."}]'::jsonb,
  null,
  array['history', 'trivia', 'latin america', 'independence']::text[],
  3,
  'published',
  false,
  false,
  now()
)
