values (
  'es-trivia-independencias-america-latina',
  'Trivia de independencias de América Latina: las guerras que liberaron un continente',
  'Ocho preguntas sobre próceres, batallas y fechas de la independencia latinoamericana, del Grito de Dolores a Ayacucho.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿En qué año comenzó Miguel Hidalgo la independencia de México con el Grito de Dolores?","options":[{"id":"a","text":"1804","is_correct":false},{"id":"b","text":"1810","is_correct":true},{"id":"c","text":"1821","is_correct":false},{"id":"d","text":"1825","is_correct":false}],"explanation":"El 16 de septiembre de 1810, Hidalgo llamó a las armas en Dolores y empezó la guerra de independencia mexicana."},{"id":"q2","question":"¿Qué líder nacido en Caracas es conocido como El Libertador por liberar gran parte de Sudamérica?","options":[{"id":"a","text":"José de San Martín","is_correct":false},{"id":"b","text":"Bernardo O''Higgins","is_correct":false},{"id":"c","text":"Simón Bolívar","is_correct":true},{"id":"d","text":"Agustín de Iturbide","is_correct":false}],"explanation":"Bolívar dirigió las campañas que liberaron Venezuela, Colombia, Ecuador, Perú y Bolivia."},{"id":"q3","question":"¿Qué país declaró su independencia el 9 de julio de 1816 en el Congreso de Tucumán?","options":[{"id":"a","text":"Chile","is_correct":false},{"id":"b","text":"Argentina","is_correct":true},{"id":"c","text":"Perú","is_correct":false},{"id":"d","text":"Uruguay","is_correct":false}],"explanation":"Las Provincias Unidas del Río de la Plata declararon la independencia en San Miguel de Tucumán."},{"id":"q4","question":"¿Quién comandó al ejército patriota en la batalla de Ayacucho de 1824, que selló la independencia del Perú?","options":[{"id":"a","text":"Simón Bolívar","is_correct":false},{"id":"b","text":"José de San Martín","is_correct":false},{"id":"c","text":"Francisco de Paula Santander","is_correct":false},{"id":"d","text":"Antonio José de Sucre","is_correct":true}],"explanation":"Sucre derrotó al ejército realista el 9 de diciembre de 1824, la última gran batalla terrestre de la independencia."},{"id":"q5","question":"¿Qué cordillera cruzó José de San Martín en 1817 para liberar Chile?","options":[{"id":"a","text":"Los Andes","is_correct":true},{"id":"b","text":"Las montañas Rocosas","is_correct":false},{"id":"c","text":"La Sierra Madre","is_correct":false},{"id":"d","text":"La meseta brasileña","is_correct":false}],"explanation":"San Martín guio al Ejército de los Andes desde Mendoza y luego ganó la batalla de Chacabuco."},{"id":"q6","question":"¿Bajo qué líder declaró Brasil su independencia de Portugal en 1822?","options":[{"id":"a","text":"Tiradentes","is_correct":false},{"id":"b","text":"Juan VI","is_correct":false},{"id":"c","text":"Pedro I","is_correct":true},{"id":"d","text":"Deodoro da Fonseca","is_correct":false}],"explanation":"Pedro I proclamó la independencia con el Grito de Ipiranga el 7 de septiembre de 1822."},{"id":"q7","question":"¿Qué nación se convirtió en el primer Estado independiente de América Latina y el Caribe en 1804?","options":[{"id":"a","text":"México","is_correct":false},{"id":"b","text":"Paraguay","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"Haití","is_correct":true}],"explanation":"Haití declaró su independencia el 1 de enero de 1804 tras la revolución de Dessalines y Louverture."},{"id":"q8","question":"¿Qué batalla de 1819 aseguró la independencia de la Nueva Granada, la actual Colombia?","options":[{"id":"a","text":"Boyacá","is_correct":true},{"id":"b","text":"Carabobo","is_correct":false},{"id":"c","text":"Chacabuco","is_correct":false},{"id":"d","text":"Pichincha","is_correct":false}],"explanation":"La victoria de Bolívar en el puente de Boyacá el 7 de agosto de 1819 abrió el camino a Bogotá."}]'::jsonb,
  null,
  array['historia', 'trivia', 'américa latina', 'independencia']::text[],
  3,
  'published',
