   is_featured, is_ai_generated, published_at)
values (
  'en-latin-america-geography-trivia',
  'Latin America Geography Trivia: Rivers, Peaks and Extremes',
  'Eight questions on the geography of Latin America: the Amazon, the Andes, deserts, lakes and the extremes of the map.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"Which Latin American river carries more water than any other river on Earth?","options":[{"id":"a","text":"The Orinoco","is_correct":false},{"id":"b","text":"The Paraná","is_correct":false},{"id":"c","text":"The Amazon","is_correct":true},{"id":"d","text":"The Magdalena","is_correct":false}],"explanation":"The Amazon discharges more water than the next several largest rivers combined."},{"id":"q2","question":"Which is the longest continental mountain range in the world?","options":[{"id":"a","text":"The Rocky Mountains","is_correct":false},{"id":"b","text":"The Himalayas","is_correct":false},{"id":"c","text":"The Alps","is_correct":false},{"id":"d","text":"The Andes","is_correct":true}],"explanation":"The Andes run about 7,000 kilometres along the western edge of South America."},{"id":"q3","question":"In which country is Aconcagua, the highest peak in the Americas?","options":[{"id":"a","text":"Chile","is_correct":false},{"id":"b","text":"Argentina","is_correct":true},{"id":"c","text":"Peru","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"Aconcagua rises 6,961 metres in Mendoza province, near the Chilean border."},{"id":"q4","question":"Which Chilean desert is considered the driest non-polar desert on Earth?","options":[{"id":"a","text":"The Atacama","is_correct":true},{"id":"b","text":"The Sonoran Desert","is_correct":false},{"id":"c","text":"The Patagonian Desert","is_correct":false},{"id":"d","text":"The Sechura Desert","is_correct":false}],"explanation":"Some weather stations in the Atacama have never recorded rainfall."},{"id":"q5","question":"Lake Titicaca, the highest navigable lake in the world, lies on the border of which two countries?","options":[{"id":"a","text":"Chile and Argentina","is_correct":false},{"id":"b","text":"Peru and Ecuador","is_correct":false},{"id":"c","text":"Peru and Bolivia","is_correct":true},{"id":"d","text":"Ecuador and Colombia","is_correct":false}],"explanation":"Titicaca sits at about 3,812 metres above sea level between Peru and Bolivia."},{"id":"q6","question":"Angel Falls, the highest uninterrupted waterfall in the world, is in which country?","options":[{"id":"a","text":"Brazil","is_correct":false},{"id":"b","text":"Guyana","is_correct":false},{"id":"c","text":"Argentina","is_correct":false},{"id":"d","text":"Venezuela","is_correct":true}],"explanation":"Angel Falls drops 979 metres in Canaima National Park, Venezuela."},{"id":"q7","question":"Which country links North and South America and is crossed by a famous canal?","options":[{"id":"a","text":"Panama","is_correct":true},{"id":"b","text":"Costa Rica","is_correct":false},{"id":"c","text":"Nicaragua","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"The Panama Canal, opened in 1914, connects the Atlantic and Pacific oceans."},{"id":"q8","question":"The Galápagos Islands belong to which country?","options":[{"id":"a","text":"Peru","is_correct":false},{"id":"b","text":"Ecuador","is_correct":true},{"id":"c","text":"Colombia","is_correct":false},{"id":"d","text":"Chile","is_correct":false}],"explanation":"The Galápagos lie about 1,000 kilometres off the coast of Ecuador."}]'::jsonb,
  null,
  array['geography', 'trivia', 'latin america', 'rivers', 'mountains']::text[],
  3,
  'published',
  false,
  false,
  now()
)
