  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"¿Qué río latinoamericano transporta más agua que cualquier otro del planeta?","options":[{"id":"a","text":"El Orinoco","is_correct":false},{"id":"b","text":"El Paraná","is_correct":false},{"id":"c","text":"El Amazonas","is_correct":true},{"id":"d","text":"El Magdalena","is_correct":false}],"explanation":"El Amazonas descarga más agua que los siguientes ríos más caudalosos juntos."},{"id":"q2","question":"¿Cuál es la cordillera continental más larga del mundo?","options":[{"id":"a","text":"Las montañas Rocosas","is_correct":false},{"id":"b","text":"El Himalaya","is_correct":false},{"id":"c","text":"Los Alpes","is_correct":false},{"id":"d","text":"Los Andes","is_correct":true}],"explanation":"Los Andes recorren unos 7.000 kilómetros por el borde occidental de Sudamérica."},{"id":"q3","question":"¿En qué país está el Aconcagua, la cumbre más alta de América?","options":[{"id":"a","text":"Chile","is_correct":false},{"id":"b","text":"Argentina","is_correct":true},{"id":"c","text":"Perú","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"El Aconcagua alcanza 6.961 metros en la provincia de Mendoza, cerca de la frontera chilena."},{"id":"q4","question":"¿Qué desierto chileno es considerado el más árido del mundo fuera de las regiones polares?","options":[{"id":"a","text":"El desierto de Atacama","is_correct":true},{"id":"b","text":"El desierto de Sonora","is_correct":false},{"id":"c","text":"El desierto patagónico","is_correct":false},{"id":"d","text":"El desierto de Sechura","is_correct":false}],"explanation":"Algunas estaciones meteorológicas del Atacama jamás han registrado lluvia."},{"id":"q5","question":"El lago Titicaca, el lago navegable más alto del mundo, está en la frontera de qué dos países?","options":[{"id":"a","text":"Chile y Argentina","is_correct":false},{"id":"b","text":"Perú y Ecuador","is_correct":false},{"id":"c","text":"Perú y Bolivia","is_correct":true},{"id":"d","text":"Ecuador y Colombia","is_correct":false}],"explanation":"El Titicaca está a unos 3.812 metros sobre el nivel del mar, entre Perú y Bolivia."},{"id":"q6","question":"¿En qué país está el Salto Ángel, la caída de agua ininterrumpida más alta del mundo?","options":[{"id":"a","text":"Brasil","is_correct":false},{"id":"b","text":"Guyana","is_correct":false},{"id":"c","text":"Argentina","is_correct":false},{"id":"d","text":"Venezuela","is_correct":true}],"explanation":"El Salto Ángel cae 979 metros en el parque nacional Canaima, en Venezuela."},{"id":"q7","question":"¿Qué país une América del Norte y del Sur y es cruzado por un famoso canal?","options":[{"id":"a","text":"Panamá","is_correct":true},{"id":"b","text":"Costa Rica","is_correct":false},{"id":"c","text":"Nicaragua","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"El canal de Panamá, inaugurado en 1914, conecta los océanos Atlántico y Pacífico."},{"id":"q8","question":"¿A qué país pertenecen las islas Galápagos?","options":[{"id":"a","text":"Perú","is_correct":false},{"id":"b","text":"Ecuador","is_correct":true},{"id":"c","text":"Colombia","is_correct":false},{"id":"d","text":"Chile","is_correct":false}],"explanation":"Las Galápagos están a unos 1.000 kilómetros de la costa de Ecuador."}]'::jsonb,
