insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-latin-music-trivia',
  'Latin Music Trivia: Where the Rhythms Were Born',
  'Eight questions on the birthplaces and pioneers of Latin music, from tango and samba to salsa, cumbia and reggaetón.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"Tango was born in the early 20th century in the port cities along which river?","options":[{"id":"a","text":"The Amazon","is_correct":false},{"id":"b","text":"The Río de la Plata","is_correct":true},{"id":"c","text":"The Orinoco","is_correct":false},{"id":"d","text":"The Magdalena","is_correct":false}],"explanation":"Tango grew in the working-class port neighbourhoods of Buenos Aires and Montevideo."},{"id":"q2","question":"In which country were both samba and bossa nova born?","options":[{"id":"a","text":"Cuba","is_correct":false},{"id":"b","text":"Argentina","is_correct":false},{"id":"c","text":"Brazil","is_correct":true},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"Samba rose in Rio de Janeiro; bossa nova followed there in the late 1950s."},{"id":"q3","question":"Cumbia originated on the Caribbean coast of which country?","options":[{"id":"a","text":"Mexico","is_correct":false},{"id":"b","text":"Peru","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"Colombia","is_correct":true}],"explanation":"Cumbia blends Indigenous, African and Spanish roots on Colombia''s Caribbean coast."},{"id":"q4","question":"Salsa took shape in the 1960s and 70s in which city, blending Cuban and Puerto Rican rhythms?","options":[{"id":"a","text":"Havana","is_correct":false},{"id":"b","text":"New York City","is_correct":true},{"id":"c","text":"San Juan","is_correct":false},{"id":"d","text":"Miami","is_correct":false}],"explanation":"The Fania label in New York turned son, mambo and guaracha into the salsa boom."},{"id":"q5","question":"Reggaetón became a mainstream genre in the late 1990s on which island?","options":[{"id":"a","text":"Cuba","is_correct":false},{"id":"b","text":"Jamaica","is_correct":false},{"id":"c","text":"Puerto Rico","is_correct":true},{"id":"d","text":"Dominican Republic","is_correct":false}],"explanation":"Built on Panama''s reggae en español, reggaetón took shape in Puerto Rico''s underground scene."},{"id":"q6","question":"Mariachi, listed by UNESCO as Intangible Cultural Heritage, is the traditional music of which country?","options":[{"id":"a","text":"Guatemala","is_correct":false},{"id":"b","text":"Spain","is_correct":false},{"id":"c","text":"Argentina","is_correct":false},{"id":"d","text":"Mexico","is_correct":true}],"explanation":"Mariachi comes from the state of Jalisco; UNESCO listed it in 2011."},{"id":"q7","question":"Merengue and bachata both come from which Caribbean country?","options":[{"id":"a","text":"Dominican Republic","is_correct":true},{"id":"b","text":"Puerto Rico","is_correct":false},{"id":"c","text":"Cuba","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"Merengue is the Dominican national dance; bachata also emerged there in the 20th century."},{"id":"q8","question":"Which singer is known worldwide as the Queen of Salsa?","options":[{"id":"a","text":"Selena","is_correct":false},{"id":"b","text":"Gloria Estefan","is_correct":false},{"id":"c","text":"Celia Cruz","is_correct":true},{"id":"d","text":"Shakira","is_correct":false}],"explanation":"Cuban-born Celia Cruz recorded for decades and became the genre''s defining voice."}]'::jsonb,
  null,
  array['music', 'trivia', 'latin america', 'salsa', 'tango']::text[],
  3,
  'published',
