  '[{"id":"q1","question":"Ceviche, fish cured in lime juice, is a national dish of which country?","options":[{"id":"a","text":"Peru","is_correct":true},{"id":"b","text":"Mexico","is_correct":false},{"id":"c","text":"Colombia","is_correct":false},{"id":"d","text":"Brazil","is_correct":false}],"explanation":"Peru claims ceviche as its national dish and celebrates a national day for it."},{"id":"q2","question":"Feijoada, a black bean and pork stew, is the signature dish of which country?","options":[{"id":"a","text":"Portugal","is_correct":false},{"id":"b","text":"Argentina","is_correct":false},{"id":"c","text":"Brazil","is_correct":true},{"id":"d","text":"Cuba","is_correct":false}],"explanation":"Feijoada completa, served with rice and orange slices, is Brazil''s best-known meal."},{"id":"q3","question":"Pupusas, thick corn tortillas stuffed with cheese or beans, are the national dish of which country?","options":[{"id":"a","text":"Honduras","is_correct":false},{"id":"b","text":"El Salvador","is_correct":true},{"id":"c","text":"Nicaragua","is_correct":false},{"id":"d","text":"Guatemala","is_correct":false}],"explanation":"Pupusas come with curtido, a pickled cabbage slaw, and have their own national day."},{"id":"q4","question":"Arepas, grilled cornmeal cakes eaten at any meal, belong to the cuisine of which two countries?","options":[{"id":"a","text":"Peru and Bolivia","is_correct":false},{"id":"b","text":"Mexico and Guatemala","is_correct":false},{"id":"c","text":"Venezuela and Colombia","is_correct":true},{"id":"d","text":"Argentina and Chile","is_correct":false}],"explanation":"Both Venezuela and Colombia claim the arepa, with different fillings and styles."},{"id":"q5","question":"Mole, a complex sauce often made with chiles and cacao, is a classic of which cuisine?","options":[{"id":"a","text":"Peruvian","is_correct":false},{"id":"b","text":"Mexican","is_correct":true},{"id":"c","text":"Brazilian","is_correct":false},{"id":"d","text":"Cuban","is_correct":false}],"explanation":"Oaxaca and Puebla are the most famous mole regions of Mexico."},{"id":"q6","question":"The potato was first domesticated thousands of years ago in which region?","options":[{"id":"a","text":"The Amazon","is_correct":false},{"id":"b","text":"Central America","is_correct":false},{"id":"c","text":"The Pampas","is_correct":false},{"id":"d","text":"The Andes","is_correct":true}],"explanation":"Andean peoples domesticated the potato in the Peru-Bolivia highlands long before it reached Europe."},{"id":"q7","question":"Mate, the shared herbal infusion, is most closely associated with which two countries?","options":[{"id":"a","text":"Argentina and Uruguay","is_correct":true},{"id":"b","text":"Chile and Peru","is_correct":false},{"id":"c","text":"Colombia and Ecuador","is_correct":false},{"id":"d","text":"Mexico and Panama","is_correct":false}],"explanation":"Mate is a daily ritual in Argentina and Uruguay, sipped through a metal straw."},{"id":"q8","question":"Asado, the ritual barbecue of beef cooked slowly over coals, is a defining tradition of which country?","options":[{"id":"a","text":"Mexico","is_correct":false},{"id":"b","text":"Venezuela","is_correct":false},{"id":"c","text":"Argentina","is_correct":true},{"id":"d","text":"Costa Rica","is_correct":false}],"explanation":"The Argentine asado is as much a social gathering as a way of cooking beef."}]'::jsonb,
