values (
  'es-trivia-comida-latinoamericana',
  'Trivia de comida latinoamericana: platos y sus países',
  'Ocho preguntas sobre platos clásicos de América Latina y de dónde vienen, del ceviche peruano a las pupusas salvadoreñas.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"El ceviche, pescado curado en jugo de limón, es plato nacional de qué país?","options":[{"id":"a","text":"Perú","is_correct":true},{"id":"b","text":"México","is_correct":false},{"id":"c","text":"Colombia","is_correct":false},{"id":"d","text":"Brasil","is_correct":false}],"explanation":"Perú reconoce el ceviche como plato nacional y le dedica un día al año."},{"id":"q2","question":"La feijoada, guiso de frijoles negros y cerdo, es el plato insignia de qué país?","options":[{"id":"a","text":"Portugal","is_correct":false},{"id":"b","text":"Argentina","is_correct":false},{"id":"c","text":"Brasil","is_correct":true},{"id":"d","text":"Cuba","is_correct":false}],"explanation":"La feijoada completa, con arroz y naranja, es la comida más conocida de Brasil."},{"id":"q3","question":"Las pupusas, tortillas gruesas rellenas de queso o frijoles, son plato nacional de qué país?","options":[{"id":"a","text":"Honduras","is_correct":false},{"id":"b","text":"El Salvador","is_correct":true},{"id":"c","text":"Nicaragua","is_correct":false},{"id":"d","text":"Guatemala","is_correct":false}],"explanation":"Las pupusas se sirven con curtido, un repollo encurtido, y tienen su propio día nacional."},{"id":"q4","question":"Las arepas, tortas de maíz a la parrilla, pertenecen a la cocina de qué dos países?","options":[{"id":"a","text":"Perú y Bolivia","is_correct":false},{"id":"b","text":"México y Guatemala","is_correct":false},{"id":"c","text":"Venezuela y Colombia","is_correct":true},{"id":"d","text":"Argentina y Chile","is_correct":false}],"explanation":"Venezuela y Colombia reclaman la arepa, con rellenos y estilos distintos."},{"id":"q5","question":"El mole, salsa compleja que suele llevar chiles y cacao, es clásico de qué cocina?","options":[{"id":"a","text":"La peruana","is_correct":false},{"id":"b","text":"La mexicana","is_correct":true},{"id":"c","text":"La brasileña","is_correct":false},{"id":"d","text":"La cubana","is_correct":false}],"explanation":"Oaxaca y Puebla son las regiones más famosas del mole mexicano."},{"id":"q6","question":"¿En qué región se domesticó la papa hace miles de años?","options":[{"id":"a","text":"El Amazonas","is_correct":false},{"id":"b","text":"Centroamérica","is_correct":false},{"id":"c","text":"La Pampa","is_correct":false},{"id":"d","text":"Los Andes","is_correct":true}],"explanation":"Los pueblos andinos domesticaron la papa en el altiplano de Perú y Bolivia mucho antes de que llegara a Europa."},{"id":"q7","question":"El mate, la infusión que se comparte, se asocia sobre todo con qué dos países?","options":[{"id":"a","text":"Argentina y Uruguay","is_correct":true},{"id":"b","text":"Chile y Perú","is_correct":false},{"id":"c","text":"Colombia y Ecuador","is_correct":false},{"id":"d","text":"México y Panamá","is_correct":false}],"explanation":"El mate es un ritual diario en Argentina y Uruguay, que se toma con bombilla."},{"id":"q8","question":"El asado, el ritual de cocinar carne a las brasas, es tradición definitoria de qué país?","options":[{"id":"a","text":"México","is_correct":false},{"id":"b","text":"Venezuela","is_correct":false},{"id":"c","text":"Argentina","is_correct":true},{"id":"d","text":"Costa Rica","is_correct":false}],"explanation":"El asado argentino es tanto una reunión social como una forma de cocinar la carne."}]'::jsonb,
