insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-latin-american-literature-trivia',
  'Latin American Literature Trivia: Boom, Nobel and Macondo',
  'Eight questions on the greats of Latin American literature: Nobel laureates, the Boom and the town of Macondo.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"Gabriel García Márquez''s One Hundred Years of Solitude is set in which fictional town?","options":[{"id":"a","text":"Comala","is_correct":false},{"id":"b","text":"Aracataca","is_correct":false},{"id":"c","text":"Macondo","is_correct":true},{"id":"d","text":"Santa María","is_correct":false}],"explanation":"Macondo was inspired by Aracataca, the author''s real hometown in Colombia."},{"id":"q2","question":"Which Chilean poet was the first Latin American to win the Nobel Prize in Literature, in 1945?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Gabriela Mistral","is_correct":true},{"id":"c","text":"Rubén Darío","is_correct":false},{"id":"d","text":"Octavio Paz","is_correct":false}],"explanation":"Gabriela Mistral won in 1945; Neruda, her compatriot, followed in 1971."},{"id":"q3","question":"In which year did Gabriel García Márquez win the Nobel Prize in Literature?","options":[{"id":"a","text":"1967","is_correct":false},{"id":"b","text":"1971","is_correct":false},{"id":"c","text":"1982","is_correct":true},{"id":"d","text":"1990","is_correct":false}],"explanation":"He won in 1982, fifteen years after publishing One Hundred Years of Solitude."},{"id":"q4","question":"Hopscotch (Rayuela), the novel that invites multiple reading orders, was written by which Argentine author?","options":[{"id":"a","text":"Jorge Luis Borges","is_correct":false},{"id":"b","text":"Julio Cortázar","is_correct":true},{"id":"c","text":"Adolfo Bioy Casares","is_correct":false},{"id":"d","text":"Ernesto Sabato","is_correct":false}],"explanation":"Cortázar published Rayuela in 1963, a landmark of the Latin American Boom."},{"id":"q5","question":"Jorge Luis Borges is best known for the collections Ficciones and which other book?","options":[{"id":"a","text":"The Aleph","is_correct":true},{"id":"b","text":"The Labyrinth of Solitude","is_correct":false},{"id":"c","text":"The Time of the Hero","is_correct":false},{"id":"d","text":"Pedro Páramo","is_correct":false}],"explanation":"The Aleph (1949) gathers some of Borges'' most famous short stories."},{"id":"q6","question":"Which Mexican writer, author of The Labyrinth of Solitude, won the Nobel Prize in 1990?","options":[{"id":"a","text":"Carlos Fuentes","is_correct":false},{"id":"b","text":"Juan Rulfo","is_correct":false},{"id":"c","text":"Octavio Paz","is_correct":true},{"id":"d","text":"Mario Vargas Llosa","is_correct":false}],"explanation":"Octavio Paz was a poet and essayist; The Labyrinth of Solitude is his best-known essay."},{"id":"q7","question":"Mario Vargas Llosa, the 2010 Nobel laureate, is from which country?","options":[{"id":"a","text":"Argentina","is_correct":false},{"id":"b","text":"Peru","is_correct":true},{"id":"c","text":"Colombia","is_correct":false},{"id":"d","text":"Chile","is_correct":false}],"explanation":"Vargas Llosa was born in Arequipa, Peru, and later also took Spanish nationality."},{"id":"q8","question":"The House of the Spirits is the debut novel of which Chilean writer?","options":[{"id":"a","text":"Laura Esquivel","is_correct":false},{"id":"b","text":"Marcela Serrano","is_correct":false},{"id":"c","text":"Gioconda Belli","is_correct":false},{"id":"d","text":"Isabel Allende","is_correct":true}],"explanation":"Published in 1982, it made Isabel Allende the most widely read Spanish-language woman author."}]'::jsonb,
  null,
  array['literature', 'trivia', 'latin america', 'nobel prize', 'books']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

